rollback.sql:
alter table referral_reward drop constraint ck_referral_reward_revocation;
alter table referral_reward drop constraint ck_referral_reward_status;
delete from referral_reward where status = 'REVOKED';
alter table referral_reward
    add constraint ck_referral_reward_status
        check (status in ('AVAILABLE', 'RESERVED', 'REDEEMED'));
